import string

def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) - ord("a") + 5) % 26) + ord("a")) if ch in string.ascii_lowercase else ch for ch in s])

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - ord("a") - 5) % 26) + ord("a")) if ch in string.ascii_lowercase else ch for ch in s])

import math

def closest_integer(value):
    '''
    Create a function that takes a value (string) representing a number
    and returns the closest integer to it. If the number is equidistant
    from two integers, round it away from zero.

    Examples
    >>> closest_integer("10")
    10
    >>> closest_integer("15.3")
    15

    Note:
    Rounding away from zero means that if the given number is equidistant
    from two integers, the one you should return is the one that is the
    farthest from zero. For example closest_integer("14.5") should
    return 15 and closest_integer("-14.5") should return -15.
    '''
    num = float(value)
    if abs(num - round(num)) == 0.5:
        if num > 0:
            return math.ceil(num)
        else:
            return math.floor(num)
    else:
        return round(num)

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1
    return 2 * (10 ** (n - 1)) - 2 * (10 ** (n - 2))

def solve(s):
    """You are given a string s.
    if s[i] is a letter, reverse its case from lower to upper or vise versa, 
    otherwise keep it as it is.
    If the string contains no letters, reverse the string.
    The function should return the resulted string.
    Examples
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    if any(c.isalpha() for c in s):
        return ''.join(c.swapcase() if c.isalpha() else c for c in s)
    else:
        return s[::-1]

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    for i in range(n // 2, 0, -1):
        if n % i == 0:
            return i
    return 1

def get_max_triples(n):
    from collections import Counter

    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = Counter(a % 3 for a in a)
    result = 0

    if count[0] >= 3:
        result += count[0] * (count[0] - 1) * (count[0] - 2) // 6

    if count[1] >= 1 and count[2] >= 1:
        result += count[1] * count[2] * count[0]

    if count[1] >= 3:
        result += count[1] * (count[1] - 1) * (count[1] - 2) // 6

